before:
countdown(start) accepts a small nonnegative integer and returns the iterable, not an array. The explicit protocol calls show the same mechanism later used by for...of. JSON.stringify omits the undefined value property at completion.
```javascript
function countdown(start) {
  return {
    [Symbol.iterator]() {
      let current = start;
      return {
        next() {
          if (current > 0) return {value: current--, done: false};
          return {value: undefined, done: true};
        }
      };
    }
  };
}
const values = countdown(2);
const iterator = values[Symbol.iterator]();
console.log(JSON.stringify(iterator.next()));
console.log(JSON.stringify(iterator.next()));
console.log(iterator.next().done);
const again = [];
for (const value of values) again.push(value);
console.log(again.join(","));
```
Output: {"value":2,"done":false}, {"value":1,"done":false}, true, then 2,1.

after:
Here is the complete example.
```javascript
function countdown(start) {
  return {
    [Symbol.iterator]() {
      let current = start;
      return {
        next() {
          if (current > 0) return {value: current--, done: false};
          return {value: undefined, done: true};
        }
      };
    }
  };
}
const values = countdown(2);
const iterator = values[Symbol.iterator]();
console.log(JSON.stringify(iterator.next()));
console.log(JSON.stringify(iterator.next()));
console.log(iterator.next().done);
const again = [];
for (const value of values) again.push(value);
console.log(again.join(","));
```
Output:
```text
{"value":2,"done":false}
{"value":1,"done":false}
true
2,1
```
The first iterator finishes. The later `for...of` asks for a new iterator, so the countdown starts again.
